<?php

namespace Volley\FaceBundle\Entity;

use Doctrine\ORM\EntityRepository;

/**
 * PostRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class PostRepository extends EntityRepository
{
    public function findAll()
    {
        return $this->findBy(array(), array('ordering' => 'DESC'));
    }

    public function findByCategory(Category $category, $count = 5, $offset = 0)
    {
        return $this->createQueryBuilder('p')
            ->select('p')
            ->innerJoin('p.category','category')
            ->andWhere('category.lft >= :lft AND category.rgt <= :rgt')
            ->setParameter('lft',$category->getLft())
            ->setParameter('rgt',$category->getRgt())
            ->andWhere('p.state > 0')
            ->andWhere('p.published <= :date')
            ->setParameter('date','now()')
            ->setMaxResults($count)
            ->setFirstResult($offset)
            ->orderBy('p.published', 'DESC')
            ->getQuery()
            ->getResult();
    }

    public function findWithOptions($slug)
    {
        return $this->createQueryBuilder('p')
            ->select('p')
            ->andWhere('p.slug = :slug')
            ->setParameter('slug',$slug)
            ->andWhere('p.state > 0')
            ->andWhere('p.published <= :date')
            ->setParameter('date','now()')
            ->getQuery()
            ->getOneOrNullResult();
    }

    /**
     * Returns post counts grouped by a DATE_FORMAT() bucket, keyed by the formatted bucket string.
     *
     * @param string    $sqlDateFormat MySQL DATE_FORMAT() pattern, e.g. '%Y-%m-%d'
     * @param \DateTime $from
     * @param \DateTime $to
     *
     * @return array Map of bucket string => integer count
     */
    public function countGroupedByPeriod($sqlDateFormat, \DateTime $from, \DateTime $to)
    {
        $connection = $this->getEntityManager()->getConnection();
        $tableName = $connection->quoteIdentifier($this->getClassMetadata()->getTableName());

        $sql = sprintf(
            'SELECT DATE_FORMAT(created, :format) AS bucket, COUNT(id) AS cnt
             FROM %s
             WHERE created BETWEEN :from AND :to
             GROUP BY bucket',
            $tableName
        );

        $statement = $connection->prepare($sql);
        $statement->bindValue('format', $sqlDateFormat);
        $statement->bindValue('from', $from->format('Y-m-d H:i:s'));
        $statement->bindValue('to', $to->format('Y-m-d H:i:s'));
        $statement->execute();

        $counts = array();
        foreach ($statement->fetchAll(\PDO::FETCH_ASSOC) as $row) {
            $counts[$row['bucket']] = (int) $row['cnt'];
        }

        return $counts;
    }
}
